-- keep Coupons.CurrentClaims consistent with the wallet rows above.
UPDATE rewards."Coupons" c SET "CurrentClaims" = COALESCE(w.cnt,0)
FROM (SELECT "CouponId", count(*) cnt FROM rewards."UserCoupons" GROUP BY 1) w
WHERE w."CouponId" = c."Id";

